# Let's understand what patterns should be caught
# Valid: {name}, {{ }, {name:d}, {name:>10}, {name!r}, etc.
# Invalid: {name, {name:d, hello {world, etc.

# A simple approach: count unescaped braces
def check_braces(fmt):
    i = 0
    while i < len(fmt):
        if fmt[i] == '{':
            if i + 1 < len(fmt) and fmt[i+1] == '{':
                i += 2  # escaped {{
                continue
            # Check if there's a matching }
            depth = 1
            j = i + 1
            while j < len(fmt) and depth > 0:
                if fmt[j] == '{':
                    if j + 1 < len(fmt) and fmt[j+1] == '{':
                        j += 2
                        continue
                    depth += 1
                elif fmt[j] == '}':
                    if j + 1 < len(fmt) and fmt[j+1] == '}':
                        j += 2
                        continue
                    depth -= 1
                j += 1
            if depth != 0:
                return False, f'unmatched opening brace at position {i}'
            i = j
        elif fmt[i] == '}':
            if i + 1 < len(fmt) and fmt[i+1] == '}':
                i += 2  # escaped }}
                continue
            return False, f'unmatched closing brace at position {i}'
        else:
            i += 1
    return True, 'ok'

tests = [
    ('{name}', True),
    ('{{ }}', True),
    ('{name:d}', True),
    ('{name', False),
    ('hello {world', False),
    ('{name:d} {n:d', False),
    ('test}}', False),
    ('{{test}}', True),
    ('a {b} c', True),
    ('a {b', False),
    ('{a.b}', True),
    ('{a[0]}', True),
    ('{a.b:c>d}', True),
]

for fmt, expected in tests:
    ok, msg = check_braces(fmt)
    status = 'PASS' if ok == expected else 'FAIL'
    print(f'{status}: {repr(fmt)} -> {ok} (expected {expected}) - {msg}')
